// ARTIST 0x82B18898.
extern "C" s32 TagFieldGetFlags(const char* pData, s32 iDefault)
{
    if (!pData) return iDefault;
    u32 uResult = 0;
    for (;; ++pData)
    {
        const s32 iCode = kFlagDecode[static_cast<s8>(*pData) + 128];
        if (iCode < 0) break;
        const u32 uShift = static_cast<u32>(iCode) & 63;
        if (uShift < 32) uResult |= 1u << uShift;
    }
    return static_cast<s32>(uResult);
}
